export const escapeAttribute=value=>String(value).replaceAll('&','&amp;').replaceAll('"','&quot;').replaceAll('<','&lt;').replaceAll('>','&gt;');
export function inlineLibrary(sources){return sources.slice(0,-1).map(source=>source.replace(/^import[^\n]*\n/gm,'').replace(/\bexport /g,'')).join('\n');}
export function buildStandalone(c,sources){
  const attrs=Object.entries({theme:c.theme,sample:c.sample||'',seed:c.seed,primary:c.primary,accent:c.accent,paper:c.paper,speed:c.speed,'reduced-motion':String(c.reducedMotion||false)}).map(([key,value])=>key+'="'+escapeAttribute(value)+'"').join(' ');
  return '<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>等绘 · 免费开源绘画</title><style>body{margin:0;background:#f7f8f5;color:#263d35;font:14px/1.8 system-ui;padding:24px}main{max-width:900px;margin:20px auto}wait-canvas{height:450px;display:block;border-radius:16px;overflow:hidden}button,select{font:inherit;border:1px solid #d5ded1;background:white;border-radius:7px;padding:7px 14px;margin:5px 6px 5px 0}small{color:#65716a}@media(max-width:600px){body{padding:14px}wait-canvas{height:300px}}</style><main><h1>让等待，慢慢成画。</h1><p>六种画法，六十幅作品 · 免费开源 · MIT</p><select id="theme" aria-label="选择画种"><option value="oil">油画</option><option value="line">线条画</option><option value="crayon">蜡笔画</option><option value="ink">国画</option><option value="sketch">素描</option><option value="pencil">彩铅画</option></select><select id="sample" aria-label="选择作品"></select><wait-canvas id="art" '+attrs+' state="idle"></wait-canvas><p id="status" role="status">准备好了。点击开始查看逐笔绘制。</p><button id="start">开始</button><button id="finished">看成品</button><button id="success">完成任务</button><button id="error">失败</button><button id="cancelled">取消</button><p><small>这是本地模拟任务，绘画进程不代表业务进度。组件和全部作品采用 MIT。</small></p><details><summary>MIT 授权</summary><pre style="white-space:pre-wrap;font-size:11px">'+escapeAttribute(sources.at(-1))+'</pre></details></main><script type="module">\n'+inlineLibrary(sources)+'\n'+
  "const art=document.getElementById('art'),status=document.getElementById('status'),selector=document.getElementById('theme'),sampleSelector=document.getElementById('sample');selector.value=art.getAttribute('theme');function renderSampleSelect(){sampleSelector.replaceChildren();for(const [id,name] of studyCatalog[selector.value]){const option=document.createElement('option');option.value=id;option.textContent=name;sampleSelector.append(option);}sampleSelector.value=resolveSample(selector.value,art.getAttribute('sample')).id;art.setAttribute('sample',sampleSelector.value);}renderSampleSelect();selector.onchange=()=>{art.setAttribute('theme',selector.value);for(const key of ['primary','accent','paper'])art.removeAttribute(key);art.removeAttribute('progress');renderSampleSelect();art.state='idle';status.textContent='已切换画种，点击开始查看过程。';};sampleSelector.onchange=()=>{art.setAttribute('sample',sampleSelector.value);art.removeAttribute('progress');art.state='idle';status.textContent='已选择作品，点击开始。';};document.getElementById('start').onclick=()=>{art.removeAttribute('progress');art.state='idle';art.state='loading';status.textContent='模拟任务处理中…';};document.getElementById('finished').onclick=()=>art.setAttribute('progress','100');for(const state of ['success','error','cancelled'])document.getElementById(state).onclick=()=>{if(art.state!=='loading')return;art.state=state;status.textContent={success:'任务完成，业务结果可以立即展示。',error:'任务失败，可以重试。',cancelled:'已取消，绘制已停止。'}[state];};\n</script></html>";
}
